import { test, expect, Page } from '@playwright/test';

test.describe('View Item Details - CRUD Operations', () => {
  let page: Page;
  const baseUrl = 'http://localhost:3000';
  const testItemName = 'Test Item';
  const testItemDescription = 'This is a test item description';

  test.beforeEach(async ({ browser }) => {
    page = await browser.newPage();
    await page.goto(baseUrl);

    // Wait for the page to load and items to be visible
    await page.waitForLoadState('networkidle');
  });

  test('should display item list on initial load', async () => {
    // Verify that the items list is visible
    const itemsList = page.getByRole('list');
    await expect(itemsList).toBeVisible();

    // Verify that at least one item is present in the list
    const listItems = page.getByRole('listitem');
    const itemCount = await listItems.count();
    expect(itemCount).toBeGreaterThan(0);
  });

  test('should open item details when clicking on an item from the list', async () => {
    // Get the first item in the list
    const firstItem = page.getByRole('listitem').first();

    // Verify the item is visible before clicking
    await expect(firstItem).toBeVisible();

    // Click on the first item to view its details
    await firstItem.click();

    // Wait for the details panel or page to load
    await page.waitForLoadState('networkidle');

    // Verify that the details view is displayed
    const detailsHeading = page.getByRole('heading', { level: 1 });
    await expect(detailsHeading).toBeVisible();
  });

  test('should display complete item details including name, description, and metadata', async () => {
    // Click on the first item to open details
    const firstItem = page.getByRole('listitem').first();
    await firstItem.click();

    // Wait for details to load
    await page.waitForLoadState('networkidle');

    // Verify item name is displayed
    const itemNameHeading = page.getByRole('heading', { level: 2 });
    await expect(itemNameHeading).toBeVisible();

    // Verify description is displayed
    const descriptionText = page.getByText(/description|details/i);
    await expect(descriptionText).toBeVisible();

    // Verify that a back button or close button exists to return to list
    const backButton = page.getByRole('button', { name: /back|close|return/i });
    await expect(backButton).toBeVisible();
  });

  test('should navigate back to item list when clicking back button', async () => {
    // Click on the first item to open details
    const firstItem = page.getByRole('listitem').first();
    await firstItem.click();

    // Wait for details to load
    await page.waitForLoadState('networkidle');

    // Verify we are in details view
    const detailsHeading = page.getByRole('heading', { level: 1 });
    await expect(detailsHeading).toBeVisible();

    // Click the back button
    const backButton = page.getByRole('button', { name: /back|close|return/i });
    await backButton.click();

    // Wait for navigation
    await page.waitForLoadState('networkidle');

    // Verify we are back at the list view
    const itemsList = page.getByRole('list');
    await expect(itemsList).toBeVisible();
  });

  test('should display correct item details for different items in the list', async () => {
    // Get all items in the list
    const listItems = page.getByRole('listitem');
    const itemCount = await listItems.count();

    // Test at least 2 items if available
    const itemsToTest = Math.min(2, itemCount);

    for (let i = 0; i < itemsToTest; i++) {
      // Click on the item at index i
      const item = page.getByRole('listitem').nth(i);
      const itemText = await item.textContent();

      await item.click();
      await page.waitForLoadState('networkidle');

      // Verify details are displayed
      const detailsContent = page.getByRole('main');
      await expect(detailsContent).toBeVisible();

      // Verify the displayed details match the clicked item
      const detailsText = await detailsContent.textContent();
      expect(detailsText).toBeTruthy();

      // Navigate back to list
      const backButton = page.getByRole('button', { name: /back|close|return/i });
      await backButton.click();
      await page.waitForLoadState('networkidle');

      // Verify we're back at the list
      const itemsList = page.getByRole('list');
      await expect(itemsList).toBeVisible();
    }
  });

  test('should display item metadata such as creation date and last modified date', async () => {
    // Click on the first item
    const firstItem = page.getByRole('listitem').first();
    await firstItem.click();

    // Wait for details to load
    await page.waitForLoadState('networkidle');

    // Look for metadata information
    const metadataSection = page.getByText(/created|modified|date|timestamp/i);

    // Verify that at least some metadata is visible
    const metadataCount = await metadataSection.count();
    expect(metadataCount).toBeGreaterThanOrEqual(0);

    // If metadata exists, verify it's visible
    if (metadataCount > 0) {
      await expect(metadataSection.first()).toBeVisible();
    }
  });

  test('should handle clicking on item with special characters in name', async () => {
    // Get all items and find one with special characters or use the first one
    const firstItem = page.getByRole('listitem').first();
    const itemContent = await firstItem.textContent();

