    await page.waitForLoadState('networkidle');

    // Verify details are displayed correctly
    const detailsHeading = page.getByRole('heading', { level: 1 });
    await expect(detailsHeading).toBeVisible();

    // Verify the content is properly rendered
    const detailsContent = await detailsHeading.textContent();
    expect(detailsContent).toBeTruthy();
    expect(detailsContent?.length).toBeGreaterThan(0);
  });
});
